import React, { useState, useEffect } from 'react';
import { Order } from '../types';
import { apiService } from '../services/apiService';
import { socketService } from '../services/socketService';

interface OrderCardProps {
  order: Order;
  onUpdate: (order: Order) => void;
  onDelete: (orderId: string) => void;
}

const OrderCard: React.FC<OrderCardProps> = ({ order, onUpdate, onDelete }) => {
  const [loading, setLoading] = useState(false);

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'PENDING':
        return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      case 'CONFIRMED':
        return 'bg-blue-100 text-blue-800 border-blue-200';
      case 'PREPARING':
        return 'bg-orange-100 text-orange-800 border-orange-200';
      case 'READY':
        return 'bg-green-100 text-green-800 border-green-200';
      case 'COMPLETED':
        return 'bg-gray-100 text-gray-800 border-gray-200';
      case 'CANCELLED':
        return 'bg-red-100 text-red-800 border-red-200';
      default:
        return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  const handleStatusChange = async (newStatus: string) => {
    setLoading(true);
    try {
      const updatedOrder = await apiService.updateOrderStatus(order._id, newStatus);
      onUpdate(updatedOrder);
    } catch (error) {
      console.error('Failed to update order:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    if (window.confirm('Are you sure you want to delete this order?')) {
      setLoading(true);
      try {
        await apiService.deleteOrder(order._id);
        onDelete(order._id);
      } catch (error) {
        console.error('Failed to delete order:', error);
      } finally {
        setLoading(false);
      }
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-md border border-gray-200 p-6 mb-4">
      <div className="flex justify-between items-start mb-4">
        <div>
          <h3 className="text-lg font-semibold text-gray-900">Order #{order.orderNumber}</h3>
          <p className="text-sm text-gray-600">Customer: {order.customerName}</p>
          {order.tableId && (
            <p className="text-sm text-gray-600">Table: {order.tableId.number}</p>
          )}
          <p className="text-sm text-gray-500">
            {new Date(order.createdAt).toLocaleString()}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <span className={`px-3 py-1 rounded-full text-sm font-medium border ${getStatusColor(order.status)}`}>
            {order.status}
          </span>
        </div>
      </div>

      <div className="mb-4">
        <h4 className="font-medium text-gray-900 mb-2">Items:</h4>
        <div className="space-y-2">
          {order.items.map((item, index) => (
            <div key={index} className="flex justify-between text-sm">
              <span>{item.quantity}x {item.productId.name}</span>
              <span className="font-medium">${(item.price * item.quantity).toFixed(2)}</span>
            </div>
          ))}
        </div>
        <div className="mt-3 pt-3 border-t border-gray-200">
          <div className="flex justify-between font-semibold">
            <span>Total:</span>
            <span>${order.totalAmount.toFixed(2)}</span>
          </div>
        </div>
      </div>

      <div className="flex gap-2 flex-wrap">
        {order.status === 'PENDING' && (
          <button
            onClick={() => handleStatusChange('CONFIRMED')}
            disabled={loading}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? '...' : 'Accept'}
          </button>
        )}

        {order.status === 'CONFIRMED' && (
          <button
            onClick={() => handleStatusChange('PREPARING')}
            disabled={loading}
            className="px-4 py-2 bg-orange-600 text-white rounded-lg hover:bg-orange-700 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? '...' : 'Start Preparing'}
          </button>
        )}

        {order.status === 'PREPARING' && (
          <button
            onClick={() => handleStatusChange('READY')}
            disabled={loading}
            className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? '...' : 'Mark Ready'}
          </button>
        )}

        {order.status === 'READY' && (
          <button
            onClick={() => handleStatusChange('COMPLETED')}
            disabled={loading}
            className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? '...' : 'Complete'}
          </button>
        )}

        {(order.status === 'PENDING' || order.status === 'CONFIRMED') && (
          <button
            onClick={() => handleStatusChange('CANCELLED')}
            disabled={loading}
            className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? '...' : 'Cancel'}
          </button>
        )}

        {order.status !== 'COMPLETED' && (
          <button
            onClick={handleDelete}
            disabled={loading}
            className="px-4 py-2 bg-red-100 text-red-700 rounded-lg hover:bg-red-200 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? '...' : 'Delete'}
          </button>
        )}
      </div>
    </div>
  );
};

export default OrderCard;
